struct Wallet { balance: int }

impl Wallet {
    fn new(start: int) -> Wallet { return Wallet { balance: start } }
    fn look(self) -> int { return self.balance }
    fn withdraw(self, n: int) -> Wallet {
        if n > self.balance { return self }      // the rule lives here only
        return Wallet { balance: self.balance - n }
    }
}

pub fn main() {
    var w = Wallet::new(50000)
    w = w.withdraw(20000)
    w = w.withdraw(999999)      // quietly refused by the rule
    wok("Balance:", w.look())
}

