fn gcd(a: int, b: int) -> int {
    let mut x = a
    let mut y = b
    while y != 0 {
        let rest = x % y
        x = y
        y = rest
    }
    return x
}

fn lcm(a: int, b: int) -> int {
    return (a * b) / gcd(a, b)
}

